#include "tapas/textension.h"

#include "../arguments.h"

#include "tapas/objects/tlist.h"
#include "runtime/value_order.h"

#include <stdlib.h>

/* No user callbacks run here. Defer comparison errors until qsort returns:
 * raising while qsort holds a moved item could strand an owned reference.
 * Validated inputs give tobj_compare a consistent category-order fallback
 * on mismatches, preserving qsort's comparator requirements before error. */
static _Thread_local int comparison_failed;

static int compare_values(const void *left, const void *right)
{
	const tobj *a = left;
	const tobj *b = right;
	int order = 0;
	int valid = a->type != tcompo && b->type != tcompo ?
		tobj_compare_numbers(a, b, &order) : tobj_compare(a, b, &order);
	if (!valid)
		comparison_failed = 1;
	return order;
}

/* Pick scalar comparators once after validation. Keeping them as leaf
 * functions avoids per-comparison tags and generic dispatch register costs. */
static int compare_integers(const void *left, const void *right)
{
	long a = ((const tobj *)left)->val.v_tint;
	long b = ((const tobj *)right)->val.v_tint;
	return (a > b) - (a < b);
}

static int compare_floats(const void *left, const void *right)
{
	double a = ((const tobj *)left)->val.v_tfloat;
	double b = ((const tobj *)right)->val.v_tfloat;
	return (a > b) - (a < b);
}

static void builtin_sort(tobj *params, uint_regs len, tobj *result)
{
	tstdlib_require_arguments("sort", len, 1);
	if (params[0].type != tcompo ||
	    tobj_compo_type(&params[0]) != compo_tlist)
		twarn(ErrRuntime_ParamsType, "sort", "");
	tlist *list = (tlist *)params[0].val.v_tcompo;
	ttypes homogeneous = list->items.len ? list->items.data[0].type : tnil;
	for (uint_count i = 0; i < list->items.len; i++) {
		if (list->items.data[i].type != homogeneous)
			homogeneous = tnil;
		if (list->items.data[i].type != tint &&
		    !tobj_is_orderable(&list->items.data[i]))
			twarn(ErrRuntime_ParamsType, "sort",
			      "non-NaN number, String or recursively orderable List required");
	}
	int (*compare)(const void *, const void *) = compare_values;
	if (homogeneous == tint)
		compare = compare_integers;
	else if (homogeneous == tfloat)
		compare = compare_floats;
	comparison_failed = 0;
	qsort(tobj_vec_data(&list->items), tobj_vec_len(&list->items),
	      sizeof(tobj), compare);
	if (comparison_failed)
		twarn(ErrRuntime_ParamsType, "sort", "incomparable elements");
	tobj_set_nil(result);
}

static const textension_symbol symbols[] = {
	{
		.name = "sort",
		.type = "Function[List] -> Nil",
		.detail = "sort(values: List) -> Nil",
		.kind = textension_function,
		.function = builtin_sort,
		.minimum_arguments = 1,
		.maximum_arguments = 1
	}
};

const textension_module tstdlib_sort_functions = {
	.scope = textension_root,
	.symbols = symbols,
	.symbol_count = sizeof(symbols) / sizeof(symbols[0])
};
